EPOCH = datetime.date(1899, 12, 30)

def to_date(v):
    if isinstance(v, (int, float)):
        return EPOCH + datetime.timedelta(days=int(v))
    if isinstance(v, datetime.datetime):
        return v.date()
    if isinstance(v, datetime.date):
        return v
    return None

# K40 = Yearly total for PE rentals in calendar year 2021
# original SUMIF range: rows 8:37, column C (commission), agent column H = "*PE*",
# closing date in column F within year 2021 ([2021-01-01, 2022-01-01)).
