end = datetime.date(2022, 1, 1)

total = 0.0
for row in range(8, 38):
    agent = ws.cell(row=row, column=8).value
    c = ws.cell(row=row, column=3).value
    f = to_date(ws.cell(row=row, column=6).value)
    if agent == 'PE' and f is not None and start <= f < end and c is not None:
        total += c

